const themes=new Set(['house','fast','countries','sports','holiday']);
function reply(v:any,status=200){return Response.json(v,{status,headers:{'Cache-Control':'no-store','Access-Control-Allow-Origin':'*'}})}
function err(m:string){return reply({error:m},400)}
function cleanName(x:any,fallback:string){const v=String(x||'').trim().replace(/[^a-zA-Z0-9 '-]/g,'').slice(0,20);return v||fallback}
function createCode(){let c='';do{c=Math.random().toString(36).slice(2,8).toUpperCase()}while(rooms.has(c));return c}
function eligible(r:R,i:number){return i>=0&&i<r.joined&&r.players[i].items.length<r.quotas[i]}
function award(r:R,w:number,price:number){if(!eligible(r,w)||price>r.players[w].budget)throw Error('Invalid allocation');r.players[w].budget-=price;r.players[w].items.push({index:r.round,price});r.history.push({index:r.round,winner:w,price});r.wonBy=w;r.soldFor=price;r.bid=price;r.phase='sold'}
function settle(r:R){if(r.leader!==null){award(r,r.leader,r.bid);return}const options=r.players.map((_,i)=>i).filter(i=>eligible(r,i));if(!options.length)throw Error('No eligible players');options.sort((a,b)=>(r.quotas[b]-r.players[b].items.length)-(r.quotas[a]-r.players[a].items.length)||a-b);award(r,options[0],0)}
function auto(r:R){
 if(r.phase!=='bidding'||r.status!=='playing')return;
 const eligibleSeats=r.players.map((_,i)=>i).filter(i=>eligible(r,i));
 if(eligibleSeats.length===1&&r.leader===null){award(r,eligibleSeats[0],0);return}
 for(let i=0;i<r.joined;i++)if(!eligible(r,i)||r.players[i].budget<=r.bid&&i!==r.leader)r.passed[i]=true;
 const challengers=eligibleSeats.filter(i=>!r.passed[i]&&i!==r.leader);
 if(!challengers.length)settle(r);
}
function cpuTurn(r:R){
 if(!r.cpu||r.status!=='playing'||r.phase!=='bidding')return;
 auto(r);
 if(r.phase!=='bidding'||r.passed[1]||!eligible(r,1)||r.leader===1)return;
 const b=r.players[1].budget,more=r.quotas[1]-r.players[1].items.length;
 const limit=Math.max(1,Math.round(b/Math.max(1,more)));
 if(b>r.bid&&(10-r.round<=more||r.bid<limit)){r.bid++;r.leader=1}else r.passed[1]=true;
 auto(r);
}
function publicRoom(r:R){const {tokens,...state}=r;return state}
function shuffle<T>(items:T[]):T[]{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function next(r:R){if(r.round>=9){r.status='finished';void aiJudge(r);return}r.round++;r.phase='bidding';r.bid=0;r.leader=null;r.passed=Array(r.joined).fill(false);r.wonBy=null;r.soldFor=0;auto(r)}
const imageCache=new Map<string,Uint8Array>();const jobs=new Set<string>();
function itemName(r:R,i:number){return r.itemDeck[i]?.[0]||'Mystery item'}
function buildPrompt(r:R,p:number){let items=r.players[p].items.map(x=>itemName(r,x.index));let base=r.theme==='house'?'A spacious green rural estate with a single elegant modern house.':r.theme==='holiday'?'A lush tropical private island with an unmistakable sandy beach and azure sea.':'A beautifully arranged diorama for the theme '+(r.customTitle||r.theme)+'.';return 'One cohesive premium 3D isometric world, aerial three-quarter camera, high quality beautiful sunlit game art. '+base+' Include these five distinct acquired items clearly and physically integrated into this one scene: '+items.join(', ')+'. Preserve the base environment, no words, no labels, no icons, no interface. Landscape framing, detailed polished architecture and scenery.'}
async function aiImage(r:R,p:number){if(!Bun.env.OPENAI_API_KEY||r.players[p].items.length!==r.quotas[p])return;const key=r.code+':'+p;if(jobs.has(key)||imageCache.has(key))return;jobs.add(key);try{const response=await fetch('https://api.openai.com/v1/images/generations',{method:'POST',signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+Bun.env.OPENAI_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:'gpt-image-1-mini',prompt:buildPrompt(r,p),size:'1024x1024',quality:'low'})});if(!response.ok){console.error('AI image status',response.status,(await response.text()).slice(0,200));return}let d=await response.json() as any;const raw=d.data?.[0]?.b64_json;if(!raw)return;imageCache.set(key,Uint8Array.from(atob(raw),x=>x.charCodeAt(0)));r.aiVersions[p]=r.quotas[p]}catch(e){console.error('AI image error',String(e))}finally{jobs.delete(key)}}
async function aiJudge(r:R){if(!Bun.env.OPENAI_API_KEY){r.aiVerdict='Judge unavailable. Compare your collections and choose your favourite.';return}try{const lists=r.players.map((p,i)=>'Player '+(i+1)+': '+p.items.map(x=>itemName(r,x.index)).join(', '));const x=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+Bun.env.OPENAI_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:'gpt-4.1-nano',max_tokens:130,messages:[{role:'system',content:'Judge this fantasy auction with 2 to 5 players fairly based on desirability and synergy of their items, not item count. Declare a winning player and give one entertaining sentence under 35 words.'},{role:'user',content:'Theme: '+(r.customTitle||r.theme)+'\n'+lists.join('\n')}]})});if(!x.ok)throw Error('Judge unavailable');if(x.ok){const d=await x.json() as any;r.aiVerdict=String(d.choices?.[0]?.message?.content||'').slice(0,350)||null}}catch(e){console.error('AI judge error');r.aiVerdict='Judge unavailable. Compare your collections and choose your favourite.'}}
async function generateTheme(topic:string):Promise<string[][]>{if(!Bun.env.OPENAI_API_KEY)throw Error('AI key not available');const x=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+Bun.env.OPENAI_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:'gpt-4.1-nano',response_format:{type:'json_object'},max_tokens:800,messages:[{role:'system',content:'Invent exactly 10 distinct items for a funny head-to-head auction theme. Nine attractive or interesting options and one rubbish option. Return ONLY JSON object with "items": array of ten objects each containing short "name" and short "description". Keep items visual and appropriate.'},{role:'user',content:topic.slice(0,65)}]})});if(!x.ok)throw Error('AI theme failed');const d=await x.json() as any;const j=JSON.parse(d.choices?.[0]?.message?.content||'{}');if(!Array.isArray(j.items)||j.items.length!==10)throw Error('AI created an invalid draft');return j.items.map((v:any)=>[String(v.name||'Surprise').slice(0,36),'',String(v.description||'Surprise reveal').slice(0,90)])}
